def rule_pipeline_facility_state_intro(doc: dict) -> list[dict]:
    try:
        import re

        state_name_pat = (
            r"Alabama|Alaska|Arizona|Arkansas|California|Colorado|Connecticut|"
            r"Delaware|Florida|Georgia|Hawaii|Idaho|Illinois|Iowa|Kansas|"
            r"Kentucky|Louisiana|Maine|Maryland|Massachusetts|Michigan|"
            r"Minnesota|Mississippi|Missouri|Montana|Nebraska|Nevada|"
            r"New Hampshire|New Jersey|New Mexico|New York|North Carolina|"
            r"North Dakota|Ohio|Oklahoma|Oregon|Pennsylvania|Rhode Island|"
            r"South Carolina|South Dakota|Tennessee|Texas|Utah|Vermont|"
            r"Virginia|Washington|West Virginia|Wisconsin|Wyoming"
        )
        state_abbrev_pat = (
            r"AL|AK|AZ|AR|CA|CO|CT|DE|FL|GA|HI|ID|IL|IA|KS|KY|LA|MD|MA|MI|"
            r"MN|MS|MO|MT|NE|NV|NH|NJ|NM|NY|NC|ND|OH|OK|PA|RI|SC|SD|TN|TX|UT|"
            r"VT|VA|WA|WV|WI|WY"
        )
        state_pat = re.compile(r"\b(?:%s|%s)\b" % (state_name_pat, state_abbrev_pat), re.I)
        intro_pat = re.compile(
            r"(?i)\b(?:located in|located at|facility in|facility located in|"
            r"facilities in|pipeline system in|pipeline systems in|"
            r"pipeline system located in|pipeline systems located in|"
            r"distribution system in|distribution systems in|control room in|"
            r"control rooms in|LNG facility in|tank farm in|terminal in|"
            r"plant in|station in|inspected(?: your)?(?: [^.\n]{0,80})?\bin)\b"
        )
        context_pat = re.compile(
            r"(?i)\b(?:facility|facilities|distribution|control room|control rooms|"
            r"terminal|plant|station|tank farm|lng|operations and maintenance|o&m|"
            r"records and facilities|interconnect|lateral|compressor|assets|well|"
            r"pipeline facility|pipeline facilities|pipeline system|pipeline systems|"
            r"pipelines|distribution system|distribution systems|inspection|"
            r"inspection system|inspection systems)\b"
        )

        def norm(text: str) -> str:
            return " ".join((text or "").split())

        def split_fragments(text: str, preserve_newlines: bool = False) -> list[str]:
            fragments = []
            if preserve_newlines:
                blocks = [norm(text)]
            else:
                blocks = re.split(r"\n+", text or "")
            for block in blocks:
                for frag in re.split(r"(?<=[.!?])\s+", block):
                    frag = norm(frag)
                    if frag:
                        fragments.append(frag)
            return fragments

        def best_snippet(text: str) -> str:
            low = text.lower()
            anchors = [
                "facility located in",
                "pipeline system located in",
                "pipeline systems located in",
                "distribution system in",
                "distribution systems in",
                "control rooms in",
                "control room in",
                "lng facility in",
                "tank farm facility in",
                "facility in",
                "located in",
                "located at",
                "terminal in",
                "plant in",
                "station in",
                "inspected",
            ]
            starts = [low.find(a) for a in anchors if low.find(a) != -1]
            if starts:
                start = min(starts)
                tail = text[start:]
                end_m = re.search(r"[.!?](?:\s|$)", tail)
                end = start + end_m.end() if end_m else len(text)
                snippet = norm(text[start:end])
                if state_pat.search(snippet):
                    snippet = re.sub(r",?\s+and the Gulf of Mexico\b.*$", "", snippet, flags=re.I).rstrip(",; ")
                    return snippet
            m = state_pat.search(text)
            if m:
                start = max(0, m.start() - 80)
                end = min(len(text), m.end() + 120)
                snippet = norm(text[start:end])
                return re.sub(r",?\s+and the Gulf of Mexico\b.*$", "", snippet, flags=re.I).rstrip(",; ")
            return ""

        sources = []
        for item in (doc.get("paragraphs") or [])[:30]:
            if item.get("text"):
                sources.append(("paragraph", item.get("page_no"), item.get("paragraph_no"), None, item["text"]))
        for item in (doc.get("lines") or [])[:120]:
            if item.get("text"):
                sources.append(("line", item.get("page_no"), None, item.get("line_no"), item["text"]))

        seen = set()
        out = []

        def add(text, page_no=None, paragraph_no=None, line_no=None):
            text = norm(text)
            if not text:
                return
            key = (text.lower(), page_no, paragraph_no, line_no)
            if key in seen:
                return
            seen.add(key)
            span = {"text": text}
            if page_no is not None:
                span["page_no"] = page_no
            if paragraph_no is not None:
                span["paragraph_no"] = paragraph_no
            if line_no is not None:
                span["line_no"] = line_no
            out.append(span)

        for kind, page_no, paragraph_no, line_no, text in sources:
            for frag in split_fragments(text, preserve_newlines=(kind == "paragraph")):
                low = frag.lower()
                if not state_pat.search(frag):
                    continue
                if intro_pat.search(frag) or (
                    ("inspected" in low or "located" in low or "facility" in low or "facilities" in low or "distribution" in low or "across" in low)
                    and context_pat.search(frag)
                ):
                    snippet = best_snippet(frag)
                    if snippet:
                        add(snippet, page_no, paragraph_no, line_no)
                if len(out) >= 4:
                    break
            if len(out) >= 4:
                break

        if not out:
            full = doc.get("text") or ""
            m = state_pat.search(full)
            if m and intro_pat.search(full):
                start = max(0, m.start() - 120)
                end = min(len(full), m.end() + 160)
                add(best_snippet(full[start:end]) or full[start:end])

        return out[:1]
    except Exception:
        return []

import re


def rule_cpf_case_number_sentence(doc: dict) -> list[dict]:
    try:
        case_pat = re.compile(
            r"\b\d{1,2}-\d{4}-\d{3,4}(?:-[A-Z]+|[A-Z])?\b",
            re.IGNORECASE,
        )
        cpf_plain_pat = re.compile(
            r"\bCPF\s+(" + case_pat.pattern[2:-2] + r")\b",
            re.IGNORECASE,
        )
        cpf_colon_pat = re.compile(
            r"\bCPF\s*:\s*(" + case_pat.pattern[2:-2] + r")\b",
            re.IGNORECASE,
        )

        lines = doc.get("lines") or []
        ordered = sorted(
            lines,
            key=lambda x: (
                x.get("page_no", 10**9),
                x.get("line_no", 10**9),
            ),
        )

        for item in ordered[:80]:
            text = (item.get("text") or "").strip()
            if not text or "CPF" not in text.upper():
                continue

            m = cpf_colon_pat.search(text)
            if m:
                return [
                    {
                        "text": f"The CPF case number assigned to this enforcement action is {m.group(1).strip()}.",
                        "page_no": item.get("page_no"),
                        "line_no": item.get("line_no"),
                    }
                ]

            m = cpf_plain_pat.search(text)
            if m:
                return [
                    {
                        "text": f"The CPF case number assigned to this enforcement action is CPF {m.group(1).strip()}.",
                        "page_no": item.get("page_no"),
                        "line_no": item.get("line_no"),
                    }
                ]

        full_text = doc.get("text") or ""
        m = cpf_colon_pat.search(full_text)
        if m:
            return [{"text": f"The CPF case number assigned to this enforcement action is {m.group(1).strip()}."}]

        m = cpf_plain_pat.search(full_text)
        if m:
            return [{"text": f"The CPF case number assigned to this enforcement action is CPF {m.group(1).strip()}."}]

        return []
    except Exception:
        return []

def _coerce_span(entry: Any) -> dict[str, Any] | None:
    if isinstance(entry, str):
        text = entry.strip()
        return {"text": text} if text else None
    if not isinstance(entry, dict):
        return None
    text = entry.get("text")
    if text is None:
        return None
    text = str(text)
    if not text.strip():
        return None
    coerced = dict(entry)
    coerced["text"] = text
    return coerced


def _span_key(span: dict[str, Any]) -> tuple[Any, ...]:
    return (
        span.get("page_no"),
        span.get("paragraph_no"),
        span.get("line_no"),
        span.get("text"),
    )


def _sort_key(span: dict[str, Any]) -> tuple[Any, ...]:
    return (
        span.get("page_no", 10**9),
        span.get("paragraph_no", 10**9),
        span.get("line_no", 10**9),
        span.get("text", ""),
    )


def _list_rule_files(rules_dir: Path, rule_names: list[str] | None = None) -> list[Path]:
    if rule_names:
        files = [rules_dir / f"{name}.py" for name in rule_names]
        return [path for path in files if path.exists()]
    return sorted(path for path in rules_dir.glob("rule_*.py") if path.is_file())


def _apply_rule_files(document: dict[str, Any], rule_files: list[Path]) -> dict[str, Any]:
    spans: list[dict[str, Any]] = []
    rules_applied: list[str] = []
    rules_no_hits: list[str] = []
    rule_errors: list[str] = []

    for rule_file in rule_files:
        rule_name = rule_file.stem
        try:
            rule_fn = _load_rule_fn(rule_file)
            raw_result = rule_fn(document)
        except Exception as exc:
            rule_errors.append(f"{rule_name}: {exc}")
            rules_no_hits.append(rule_name)
            continue

        if not isinstance(raw_result, list):
            rules_no_hits.append(rule_name)
            continue

        coerced = [_coerce_span(item) for item in raw_result]
        cleaned = [item for item in coerced if item]
        if cleaned:
            spans.extend(cleaned)
            rules_applied.append(rule_name)
        else:
            rules_no_hits.append(rule_name)

    deduped: list[dict[str, Any]] = []
    seen: set[tuple[Any, ...]] = set()
    for span in spans:
        key = _span_key(span)
        if key in seen:
            continue
        seen.add(key)
        deduped.append(span)

    deduped.sort(key=_sort_key)
    retrieved_text = "\n\n".join(span["text"] for span in deduped) if deduped else ""

    return {
        "retrieved_spans": deduped,
        "retrieved_text": retrieved_text,
        "retrieved_token_count": _count_tokens(retrieved_text),
        "rules_applied": rules_applied,
        "rules_no_hits": rules_no_hits,
        "rule_errors": rule_errors,
    }


def _qa_call(question: str, retrieved_text: str, *, model_name: str = "gpt54") -> tuple[str | None, int, int, float]:
    model_mod = importlib.import_module(f"models.{model_name}")
    t0 = time.time()
    response = model_mod.client.chat.completions.create(
        model=model_mod.AZURE_DEPLOYMENT,
        messages=[
            {"role": "system", "content": _QA_SYSTEM},
            {"role": "user", "content": f"Passage:\n{retrieved_text}\n\nQuestion: {question}"},
        ],
        max_completion_tokens=500,
        temperature=0.0,
    )
    latency = round(time.time() - t0, 3)
    answer = (response.choices[0].message.content or "").strip() or None
    usage = response.usage
    return (
        answer,
        int(usage.prompt_tokens if usage else 0),
        int(usage.completion_tokens if usage else 0),
        latency,
    )


def _judge_call(
    dataset_name: str,
    question: str,
    ground_truth: Any,
    predicted: Any,
) -> tuple[bool, int, int]:
    if ground_truth is None or predicted is None:
        return False, 0, 0

    model_mod = importlib.import_module("models.gpt54")
    gt_str = json.dumps(ground_truth) if not isinstance(ground_truth, str) else ground_truth
    pred_str = str(predicted)
    response = model_mod.client.chat.completions.create(
        model=model_mod.AZURE_DEPLOYMENT,
        messages=[
            {
                "role": "system",
                "content": _JUDGE_SYSTEM_BY_DATASET.get(dataset_name, _JUDGE_SYSTEM_GENERIC),
            },
            {
                "role": "user",
                "content": f"Question: {question}\nGround Truth: {gt_str}\nPredicted: {pred_str}",
            },
        ],
        max_completion_tokens=10,
        temperature=0.0,
    )
    verdict = (response.choices[0].message.content or "").strip().lower()
    usage = response.usage
    return (
        verdict == "correct",
        int(usage.prompt_tokens if usage else 0),
        int(usage.completion_tokens if usage else 0),
    )


def _clean_stderr(stderr: str) -> str:
    lines = [
        line
        for line in stderr.splitlines()
        if line.strip() != "Reading additional input from stdin..."
    ]
    return "\n".join(lines).strip()[:4000]


